namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentCode { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Invalid Student ID format.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "HIST", Name = "History" }
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Programming",
            Description = "Fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",
            InstructorName = "Dr. Alice Chen",
            InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS education pedagogy.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms",
            Description = "Advanced data structures including trees, graphs, and hash tables. Algorithm analysis and design techniques.",
            Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM",
            InstructorName = "Dr. Bob Martinez",
            InstructorBio = "Dr. Martinez specializes in algorithm design and competitive programming. He coaches the university's ICPC team.",
            DepartmentCode = "CS", IsFeatured = true
        },
        new()
        {
            Id = 3, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.",
            Credits = 3, Schedule = "Mon/Wed 1:00–2:15 PM",
            InstructorName = "Dr. Carol Singh",
            InstructorBio = "Dr. Singh's research focuses on applied linear algebra and numerical methods. She has authored two textbooks on the subject.",
            DepartmentCode = "MATH", IsFeatured = false
        },
        new()
        {
            Id = 4, Code = "MATH 301", Title = "Probability and Statistics",
            Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.",
            Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM",
            InstructorName = "Dr. David Park",
            InstructorBio = "Dr. Park is a statistician with industry experience in data science. He brings real-world datasets into the classroom.",
            DepartmentCode = "MATH", IsFeatured = true
        },
        new()
        {
            Id = 5, Code = "ENG 101", Title = "Composition and Rhetoric",
            Description = "Developing clear, effective writing through essays, research papers, and rhetorical analysis of texts.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM",
            InstructorName = "Prof. Emily Watts",
            InstructorBio = "Prof. Watts is a published author and writing consultant who has helped thousands of students improve their academic writing.",
            DepartmentCode = "ENG", IsFeatured = false
        },
        new()
        {
            Id = 6, Code = "ENG 250", Title = "American Literature",
            Description = "Survey of American literary works from the colonial period to the present, covering major movements and authors.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM",
            InstructorName = "Dr. Frank Okafor",
            InstructorBio = "Dr. Okafor is an award-winning literary critic specializing in 20th-century American fiction and postcolonial literature.",
            DepartmentCode = "ENG", IsFeatured = false
        },
        new()
        {
            Id = 7, Code = "PHYS 201", Title = "Classical Mechanics",
            Description = "Newtonian mechanics, energy, momentum, rotational dynamics, oscillations, and gravitational systems.",
            Credits = 4, Schedule = "Mon/Wed/Fri 2:00–2:50 PM + Lab Thu 3:00–5:00 PM",
            InstructorName = "Dr. Grace Liu",
            InstructorBio = "Dr. Liu is an experimental physicist whose research includes nanomechanics and precision measurement techniques.",
            DepartmentCode = "PHYS", IsFeatured = true
        },
        new()
        {
            Id = 8, Code = "PHYS 310", Title = "Quantum Mechanics",
            Description = "Wave-particle duality, Schrödinger equation, quantum states, operators, and applications to atomic systems.",
            Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM",
            InstructorName = "Dr. Henry Novak",
            InstructorBio = "Dr. Novak is a theoretical physicist researching quantum information and computation. He holds two patents in quantum sensing.",
            DepartmentCode = "PHYS", IsFeatured = false
        },
        new()
        {
            Id = 9, Code = "HIST 101", Title = "World History to 1500",
            Description = "Survey of major civilizations, trade networks, and cultural developments from prehistory through the medieval period.",
            Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM",
            InstructorName = "Dr. Irene Vasquez",
            InstructorBio = "Dr. Vasquez is an archaeologist and historian who has led excavations in Mesoamerica and the Mediterranean.",
            DepartmentCode = "HIST", IsFeatured = false
        },
        new()
        {
            Id = 10, Code = "HIST 350", Title = "Modern European History",
            Description = "Europe from the French Revolution to the present: industrialization, nationalism, world wars, and the EU.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM",
            InstructorName = "Dr. James O'Brien",
            InstructorBio = "Dr. O'Brien specializes in 20th-century European diplomatic history and has served as a visiting scholar at Oxford.",
            DepartmentCode = "HIST", IsFeatured = false
        }
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> SearchCourses(string? query, string? departmentCode)
    {
        var results = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            results = results.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(query))
        {
            results = results.Where(c =>
                c.Title.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(query, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

